158				c := code
159				commands[i].exitCode = &c
160				commands[i].failed = code != 0
161			} else if failedByCall[commands[i].callID] {
162				commands[i].failed = true
163			}
164		}
165		return tools, commands, dedupeFileRefs(files)
166	}
